package net.officefloor.hq.app.person;

/** A person on a sheet. Mutable so an Apply step changes it in place. */
public class Person {

    private final long id;
    private final String sheetId;
    private String name;
    private String grade;

    public Person(long id, String sheetId, String name, String grade) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getGrade() { return grade; }
    public void setGrade(String grade) { this.grade = grade; }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Person person = repository.findById(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonRepository repository) {
        repository.save(person);
    }
}
package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        String name = request == null ? null : request.name();
        String grade = request == null ? null : request.grade();
        if (name == null || name.isBlank()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (grade == null || !GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        // Stored without surrounding spaces.
        body.set(new PersonRequest(name.strip(), grade));
    }
}
package net.officefloor.hq.app.person;

/** The person form: the request body to add or edit a person. */
public record PersonRequest(String name, String grade) {
}
package net.officefloor.hq.app.person;

/** A person as the screen shows it. */
public record PersonResponse(long id, String name, String grade) {
    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person) {
        person.setName(request.name());
        person.setGrade(request.grade());
    }
}
